package com.mythix.tcg.admin.api;
import com.mythix.tcg.admin.persistence.AuditLogRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/audit-logs") @RequiredArgsConstructor public class AdminAuditLogsController { private final AuditLogRepository logs; @GetMapping public Page<AuditLogResponse> list(@RequestParam(required=false) String action,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size){var p=PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size)));return (action==null||action.isBlank()?logs.findAllByOrderByCreatedAtDesc(p):logs.findByActionOrderByCreatedAtDesc(action,p)).map(AuditLogResponse::from);} }
